const saveTimers=new WeakMap(),saveQueues=new WeakMap();async function sendHx(f){const u=f.getAttribute('hx-post'),t=document.querySelector(f.getAttribute('hx-target')),swap=f.getAttribute('hx-swap');if(t&&swap!=='outerHTML')t.textContent='Сохраняется…';f.setAttribute('aria-busy','true');try{const r=await fetch(u,{method:'POST',body:new FormData(f),credentials:'same-origin',headers:{'HX-Request':'true'}}),h=await r.text();if(!r.ok)throw new Error(h);if(t){if(swap==='outerHTML')t.outerHTML=h;else t.innerHTML=h}const included=f.elements.included;if(included)f.closest('.review-card')?.classList.toggle('excluded',!included.checked)}catch(_){if(t&&swap!=='outerHTML')t.textContent='Ошибка сохранения';else alert('Не удалось изменить изображение')}finally{f.removeAttribute('aria-busy')}}function queueSave(f){const previous=saveQueues.get(f)||Promise.resolve(),next=previous.then(()=>sendHx(f));saveQueues.set(f,next);return next}document.addEventListener('input',e=>{const f=e.target.closest?.('form.card-editor');if(!f)return;clearTimeout(saveTimers.get(f));const t=document.querySelector(f.getAttribute('hx-target'));if(t)t.textContent='Есть несохранённые изменения';saveTimers.set(f,setTimeout(()=>{saveTimers.delete(f);queueSave(f)},700))});document.addEventListener('change',e=>{const f=e.target.closest?.('form.card-editor');if(f){clearTimeout(saveTimers.get(f));saveTimers.delete(f);queueSave(f)}});document.addEventListener('submit',async e=>{const f=e.target,u=f.getAttribute('hx-post');if(!u)return;e.preventDefault();if(f.classList.contains('card-editor')){clearTimeout(saveTimers.get(f));saveTimers.delete(f);await queueSave(f);return}const editor=f.closest('.review-card')?.querySelector('form.card-editor');if(editor&&saveTimers.has(editor)){clearTimeout(saveTimers.get(editor));saveTimers.delete(editor);await queueSave(editor)}await sendHx(f)});
